-- Sesión 51 — Zonas de caza (generado por gen_zones.mjs a partir de client/src/shared/hunting_zones.js)
-- 1) Quitar los monstruos repartidos por toda la isla (solo los de las zonas;
--    no toca jefes, cuevas, poblado guanche, Fosa ni criaturas temporales).
DELETE FROM npc_instances
 WHERE owner_user_id IS NULL AND expires_at IS NULL
   AND def_id IN ('chicken','cow','rat','rat_jefe','spider','spider_jefe','wolf','wolf_jefe','boar','boar_jefe','scorpion','scorpion_jefe','golem','golem_jefe','yeti','yeti_jefe','ogro_anaga','ogro_anaga_jefe','goblin','goblin_jefe','bandido','bandido_jefe','skeleton','skeleton_jefe','zombi','zombi_jefe','zombi_igneo','zombi_igneo_jefe')
   AND x BETWEEN -2100 AND 2100 AND z BETWEEN -2100 AND 2100;
